function focusCitation(message:string,index:number){const key=message+":"+index;if(expanded.value===key){expanded.value="";return}expanded.value=key;void nextTick(()=>document.getElementById("assistant-citation-"+message+"-"+index)?.focus())}function openAttachment(){if(!attachment.value)return;const event=attachment.value.id;if(matchMedia("(max-width:900px)").matches)open.value=false;void router.push({path:route.path,query:{...route.query,event}})}function attach(e:Event){const d=(e as CustomEvent<Attachment>).detail;if(!d)return;setLaunchOrigin();if(!active.value)create();attachment.value=d;open.value=true;void nextTick(()=>document.querySelector<HTMLTextAreaElement>(".assistant-composer textarea")?.focus())}function validUrl(v:string){return /^https:\/\//i.test(v)}function readingUrl(url:string){return preferredReadingUrl(url,locale.value)}function onKey(e:KeyboardEvent){if(e.key==="Escape"&&scopeDetails.value?.open){e.preventDefault();e.stopImmediatePropagation();scopeDetails.value.open=false;return}if(e.key==="Escape"&&menuTarget.value){e.preventDefault();e.stopImmediatePropagation();menuTarget.value="";return}if(e.key==="Escape"&&open.value&&historyOpen.value&&!document.querySelector("dialog[open],.range-popover")){e.preventDefault();historyOpen.value=false;void nextTick(()=>document.querySelector<HTMLButtonElement>("[data-testid=history-toggle]")?.focus());return}if(e.key==="Escape"&&open.value&&!e.defaultPrevented&&!document.querySelector("dialog[open],.range-popover")){e.preventDefault();close()}}function trap(e:KeyboardEvent){if(e.key!=="Tab"||!matchMedia("(max-width:900px)").matches)return;const a=[...document.querySelectorAll<HTMLElement>("#global-assistant button,#global-assistant textarea,#global-assistant a,#global-assistant [role=separator],#global-assistant summary,#global-assistant .assistant-messages")].filter(x=>!x.hasAttribute("disabled")&&x.getClientRects().length>0),f=a[0],l=a.at(-1);if(!f||!l)return;if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}function onResize(){compact.value=matchMedia("(max-width:900px)").matches;widths();mobile()}function mobile(){const v=Boolean(route.query.event||route.query.source||route.query.evidence)||(open.value&&matchMedia("(max-width:900px)").matches);document.querySelector(".app-content main")?.toggleAttribute("inert",v);document.querySelector(".app-rail")?.toggleAttribute("inert",v)}
watch(assistantScope,s=>{pendingScope.value=clone(s);if(!running.value&&messages.value.length===0)activeScope.value=clone(s)},{deep:true,immediate:true});watch(open,v=>{if(v){document.documentElement.classList.add("global-assistant-open");mobile()}});watch(panelWidth,widths);watch(historyOpen,()=>widths());onMounted(async()=>{syncMotionVariables();messageObserver=new ResizeObserver(layoutRound);document.addEventListener("pointerdown",scopeOutside);compact.value=matchMedia("(max-width:900px)").matches;try{const savedPanel=Number(localStorage.getItem("assistant-width")),savedHistory=Number(localStorage.getItem("history-width"));panelWidth.value=Number.isFinite(savedPanel)&&savedPanel>0?Math.min(innerWidth*.5,savedPanel):460;historyWidth.value=Number.isFinite(savedHistory)&&savedHistory>=0?savedHistory:220}catch{storageState.failed=true}conversations.value=await loadConversations();const saved=await loadActiveConversation();activate(conversations.value.some(x=>x.id===saved)?saved:conversations.value[0]?.id||"");widths();window.addEventListener("attach-event",attach as EventListener);document.addEventListener("keydown",onKey,true);document.addEventListener("pointerdown",dismissMenu);window.addEventListener("resize",onResize)});onBeforeUnmount(()=>{cancel();messageObserver?.disconnect();cancelAnimationFrame(anchorAnimation);cancelAnimationFrame(layoutFrame);document.removeEventListener("pointerdown",scopeOutside);window.removeEventListener("attach-event",attach as EventListener);document.removeEventListener("keydown",onKey,true);document.removeEventListener("pointerdown",dismissMenu);window.removeEventListener("resize",onResize);document.querySelector(".app-content main")?.removeAttribute("inert");document.querySelector(".app-rail")?.removeAttribute("inert");document.documentElement.classList.remove("global-assistant-open")})
</script>
<template><Teleport to="body"><button class="assistant-trigger" :class="{'assistant-trigger--mobile':compact}" data-testid="assistant-toggle" :aria-expanded="open" aria-controls="global-assistant" :aria-label="tr('打开研究助手', 'Open research assistant')" :title="tr('研究助手', 'Research assistant')" @click="openPanel"><AssistantMark /></button></Teleport><Transition name="assistant-launch" @after-leave="finishClose"><aside v-show="open" id="global-assistant" class="assistant-panel assistant-workspace assistant-reading-timeline" data-testid="global-assistant" :style="{width:panelWidth+'px'}" :inert="!open" :aria-label="tr('全站研究助手', 'Site research assistant')" @keydown="trap"><div role="separator" tabindex="0" aria-orientation="vertical" :aria-valuenow="Math.round(panelWidth)" class="assistant-resizer" data-testid="assistant-resizer" :aria-label="tr('调整助手宽度（Alt 加方向键）', 'Resize assistant width (Alt + arrow keys)')" @pointerdown="resize($event,'panel')" @keydown="keyResize($event,'panel')"></div><section class="assistant-main" :class="{'has-messages':messages.length}"><header class="assistant-panel__header"><div class="assistant-heading"><AssistantMark /><strong>{{ tr("研究助手", "Research assistant") }}</strong></div><div class="assistant-header-tools"><button class="assistant-icon-control" data-testid="history-toggle" :aria-expanded="historyOpen" :title="tr('历史会话', 'Conversations')" :aria-label="tr('历史会话', 'Conversations')" @click="toggleHistory"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/></svg></button><button class="assistant-icon-control" data-testid="new-conversation" :title="tr('新建会话', 'New conversation')" :aria-label="tr('新建会话', 'New conversation')" @click="create"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 8v8m-4-4h8"/></svg></button><button class="assistant-close quiet-button icon-button" :title="tr('收起研究助手', 'Close research assistant')" :aria-label="tr('收起研究助手', 'Close research assistant')" @click="close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></div></header><div class="assistant-scope-bar"><details ref="scopeDetails" class="assistant-scope-menu"><summary :class="{'scope-changed':scopeChanged}">{{scopeChanged?tr('范围已变化','Scope changed'):tr('研究范围','Research scope')}}</summary><div class="assistant-scope-popover"><strong>{{activeScope.label}}</strong><p class="meta">{{activeScope.snapshot}}</p><template v-if="scopeChanged"><p class="meta">{{ tr("页面范围已变化，之前的回答仍保留原范围。", "The page scope changed; earlier answers retain their original scope.") }}</p><p class="meta">{{ tr("新范围：", "New scope:") }}{{pendingScope.snapshot}}</p><button @click="applyCurrentScope">{{ tr("采用此页面的新范围", "Use this page’s new scope") }}</button></template></div></details><span class="meta">{{mode==='demo'?tr('演示会话','Demo conversation'):tr('基于库内来源','Library sources')}}</span></div><p v-if="attachment" class="assistant-attachment" data-testid="attached-event"><span>{{ tr("下一问依据：", "For the next question:") }} {{attachment.title}}</span><span class="assistant-attachment-actions"><button class="assistant-icon-control" :title="tr('查看事件', 'View event')" :aria-label="tr('查看事件', 'View event')" @click="openAttachment"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14v16H5zM8 8h8m-8 4h8m-8 4h5"/></svg></button><button class="assistant-icon-control" :title="tr('移除', 'Remove')" :aria-label="tr('移除', 'Remove')" @click="attachment=undefined"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button></span></p><p v-if="storageState.failed" class="error" role="alert">{{ tr("浏览器存储不可用，当前会话仅保存在内存中；仍可导出。", "Browser storage is unavailable; this conversation is kept only in memory and can still be exported.") }}</p><div class="assistant-stage" :aria-hidden="!messages.length" :inert="!messages.length"><div ref="messageViewport" class="assistant-messages" tabindex="0" :aria-label="tr('会话内容', 'Conversation content')" data-testid="conversation-messages" @scroll="onMessageScroll" @wheel.passive="releaseAnchor" @touchstart.passive="releaseAnchor" @pointerdown="releaseAnchor"><div ref="messageContent" class="assistant-message-content"><article v-for="m in messages" :key="m.id" :id="'message-'+m.id" class="conversation-turn" data-testid="conversation-turn" :class="m.role"><p class="meta turn-context"><strong class="turn-role" :data-role="m.role">{{ m.role==='user'?tr('你','You'):tr('助手','Assistant') }}</strong><span class="turn-mode" :data-mode="m.mode" :title="m.mode==='demo'?tr('前端模拟数据','Frontend simulation'):tr('库内数据','Library data')">{{ m.mode==='demo'?tr('模拟','Demo'):tr('库内','Library') }}</span></p><p v-if="m.mode==='demo'&&m.role==='assistant'" class="demo">{{ tr("模拟流，仅用于演示。", "Simulated stream — for demonstration only.") }}</p><p v-if="m.role==='assistant'&&m.status==='running'" class="meta">{{ tr("正在生成，以下为未校验草稿。", "Generating — the text below is an unverified draft.") }}</p><p v-if="m.role==='assistant'&&m.status==='error'&&m.text" class="meta">{{ tr("回答未完成，以下为保留草稿。", "The answer was not completed; the draft below is preserved.") }}</p><MarkdownText class="answer-body" :text="displayText(m)" /><p v-if="m.status === 'cancelled' || m.status === 'interrupted'" class="meta">{{ m.status === 'cancelled' ? tr('已取消，未自动重试。','Cancelled; not retried automatically.') : tr('请求已中断，未自动重试。','Request interrupted; not retried automatically.') }}</p><p v-if="m.metrics?.coverage === 'partial'" class="meta">{{ tr("覆盖不完整：答案仅基于部分匹配资料。", "Incomplete coverage: the answer uses only part of the matching material.") }}</p><p v-if="m.attachment" class="meta">{{ tr("下一问依据：", "For the next question:") }} {{ m.attachment.title }}</p><details class="turn-details" data-testid="turn-details"><summary>{{ m.citations?.length?tr("来源与详情 · {count}","Sources & details · {count}",{count:m.citations?.length}):tr("详情","Details") }}</summary><p v-if="m.error" class="error"><strong>{{m.error.code}}</strong>：{{m.error.message}}</p><p class="meta">{{ m.scope }}</p><section v-if="m.plan" class="query-plan assistant-plan"><h2>{{ tr("检索范围", "Search scope") }}</h2><p>{{ tr("业务日期：", "Business date:") }}{{m.plan.business_date}} · {{ tr("时区：", "Timezone:") }}{{m.plan.timezone}}</p><p>{{ tr("分类：", "Category:") }}{{categoryLabel(m.plan.filters.category)}} · {{ tr("日期：", "Dates:") }}{{dateLabel(m.plan.filters.date_from)}} {{ tr("至", "to") }} {{dateLabel(m.plan.filters.date_to)}} {{ tr("（起止日期均包含）。", "(inclusive).") }}</p><p>{{ tr("实体：", "Entities:") }}{{m.plan.filters.entity_ids?.length?tr(m.plan.filters.entity_match==='all'?"同时匹配 {count} 个实体":"任一匹配 {count} 个实体",m.plan.filters.entity_match==='all'?"Match all {count} entities":"Match any {count} entities",{count:m.plan.filters.entity_ids.length}):tr("未限定实体","No entity limit")}}</p><p v-if="m.plan.entity_roles?.length">{{ tr("实体角色：", "Entity roles:") }}{{m.plan.entity_roles.map(roleLabel).join(locale==='zh'?'、':', ')}}</p><p v-if="m.plan.requires_clarification">{{ tr("需要澄清：", "Clarification needed:") }}{{m.plan.clarification_candidates.map(x=>x.label).join(locale==='zh'?'、':', ')}}</p><p v-if="m.plan.free_text">{{ tr("未理解限制：", "Unrecognized constraint:") }}{{m.plan.free_text}}</p><p v-if="m.plan.history_turns_considered !== undefined" class="meta">{{ tr("已参考历史 {total} 轮，其中用户问题 {used} 轮。", "Used {total} earlier turns, including {used} user questions.", {total:m.plan.history_turns_considered,used:m.plan.history_user_turns_used||0}) }}</p><p v-if="m.plan.filters.event_ids?.length" class="meta">{{ tr("附加事件：{count} 个。", "Attached events: {count}.", {count:m.plan.filters.event_ids.length}) }}</p><ul v-if="m.plan.event_targets?.length" class="meta"><li v-for="target in m.plan.event_targets" :key="target.event_id">{{tr("附件 {title}：{status}", "Attachment {title}: {status}", {title:target.title_zh||target.event_id,status:targetStatus(target.status)})}}</li></ul><ul v-if="m.plan.warnings.length"><li v-for="w in m.plan.warnings" :key="w">{{w}}</li></ul></section><div v-for="c in m.citations" :key="m.id+'-'+c.index" class="evidence-item"><button :aria-expanded="expanded===m.id+':'+c.index" :aria-controls="'assistant-citation-'+m.id+'-'+c.index" @click="focusCitation(m.id,c.index)">[{{c.index}}] {{c.title}}</button><blockquote v-if="expanded===m.id+':'+c.index" :id="'assistant-citation-'+m.id+'-'+c.index" tabindex="-1">{{c.quote_text||tr('无段落摘录','No excerpt available')}}<footer class="meta">{{ tr("段落", "Paragraph") }} {{c.paragraph_id||tr("未提供", "Not provided")}}</footer></blockquote><a v-if="validUrl(c.source_url)" :href="readingUrl(c.source_url)" target="_blank" rel="noopener">{{ readingUrl(c.source_url) === c.source_url ? tr("打开来源", "Open source") : tr("打开中文页面", "Open Chinese page") }}</a><a v-if="validUrl(c.source_url) && readingUrl(c.source_url) !== c.source_url" :href="c.source_url" target="_blank" rel="noopener">{{ tr("查看采集原文（英文摘录核验）", "View collected original (verify English excerpt)") }}</a></div><p v-if="m.metrics" class="meta tabular turn-metrics"><span>{{ tr("完整匹配 ", "Exact matches ") }}<b>{{m.metrics.scope_total}}</b></span><span>{{ tr("取回 ", "Retrieved ") }}<b>{{m.metrics.retrieved_count}}</b></span><span>{{ tr("总结 ", "Summarized ") }}<b>{{m.metrics.summarized_count}}</b></span><span>{{ tr("引用 ", "Citations ") }}<b>{{m.metrics.citation_count}}</b></span><span class="turn-coverage" :data-coverage="m.metrics.coverage">{{ tr("覆盖：", "Coverage:") }}{{m.metrics.coverage}}</span></p></details><button v-if="m.plan&&(m.text==='规则解析预览'||m.text==='Rule parse preview')" @click="applyRulePlan(m.plan)">{{ tr("应用到总览", "Apply to overview") }}</button></article></div><div class="assistant-round-spacer" :style="{height:roundSpacer+'px'}" aria-hidden="true"></div></div><button v-if="messages.length&&!atBottom" class="assistant-icon-control latest-message" :class="{'is-running':running}" :title="tr('回到最新消息', 'Back to latest message')" :aria-label="tr('回到最新消息', 'Back to latest message')" @click="scrollBottom"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button></div><p v-if="!messages.length" class="assistant-empty">{{ tr("输入问题开始研究；范围会随本轮记录。", "Ask a question to begin research; the scope is recorded with this turn.") }}</p><footer class="assistant-dock"><div class="assistant-composer ask-question" data-testid="assistant-composer"><div class="composer-heading"><label for="assistant-question">{{ tr("问题", "Question") }}</label></div><MarkdownText v-if="previewDraft" class="draft-preview" :text="draft" /><textarea v-show="!previewDraft" id="assistant-question" v-model="draft" rows="3" :placeholder="tr('输入需要核查的问题', 'Enter a question to verify')" aria-describedby="composer-key-hint" @keydown="composerKey" /><p v-if="scopeIssue" class="error" role="alert">{{scopeIssue}}</p><div class="assistant-toolbar"><button class="assistant-icon-control" :aria-pressed="previewDraft" :disabled="!draft" :title="previewDraft?tr('继续编辑','Continue editing'):tr('预览','Preview')" :aria-label="previewDraft?tr('继续编辑','Continue editing'):tr('预览','Preview')" @click="previewDraft=!previewDraft"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4zM8 9h8M8 13h5"/></svg></button><button class="assistant-icon-control" :disabled="running||!draft.trim()" :title="tr('按问题筛选', 'Filter by question')" :aria-label="tr('按问题筛选', 'Filter by question')" @click="planQuestion"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16l-6 7v5l-4 2v-7z"/></svg></button><span class="assistant-toolbar-spacer"></span><button class="assistant-icon-control assistant-send" :class="{'is-stop':running}" :aria-disabled="!running&&!canSubmit" :title="sendHint" :aria-label="sendHint" @click="running?cancel():submit()"><svg v-if="running" viewBox="0 0 24 24" aria-hidden="true"><rect x="7" y="7" width="10" height="10" rx="1" fill="currentColor" stroke="none"/></svg><svg v-else viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5m-6 6 6-6 6 6"/></svg></button></div></div><p v-if="quotaCopy&&!isDemo()" class="meta assistant-quota" aria-live="polite">{{quotaCopy}}</p><p id="composer-key-hint" class="meta composer-key-hint">{{ tr("Enter 发送 · Ctrl+Enter 换行 · 支持 Markdown", "Enter to send · Ctrl+Enter for a line break · Markdown supported") }}</p><p v-if="status" class="meta assistant-status" aria-live="polite">{{statusCopy(status)}}</p></footer></section><aside v-if="historyOpen" class="history-panel" :aria-label="tr('研究会话历史', 'Research conversation history')" data-testid="history-panel" :style="{width:historyWidth+'px'}">
<div role="separator" tabindex="0" aria-orientation="vertical" :aria-valuenow="Math.round(historyWidth)" class="history-resizer" data-testid="history-resizer" :aria-label="tr('调整历史宽度（Alt 加方向键）', 'Resize history width (Alt + arrow keys)')" @pointerdown="resize($event,'history')" @keydown="keyResize($event,'history')"></div>
<div class="history-heading"><span>{{ tr("历史会话", "Conversations") }}</span><button class="history-collapse quiet-button icon-button" :title="compact?tr('返回对话','Back to conversation'):tr('收起','Close')" :aria-label="compact?tr('返回对话','Back to conversation'):tr('收起','Close')" @click="historyOpen=false"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="compact ? 'm15 18-6-6 6-6' : 'm9 18 6-6-6-6'"/></svg></button></div>
<div v-for="x in conversations" :key="x.id" class="history-row" :class="{active:x.id===activeId}">
<button class="history-title" data-testid="history-item" :data-conversation-id="x.id" :title="x.title" :aria-current="x.id===activeId?'true':undefined" @click="selectConversation(x.id); compact && (historyOpen=false)">{{x.title}}</button>
<button class="history-more icon-button quiet-button" data-testid="history-more" :aria-label="tr('{title} 的更多操作', 'More actions for {title}', { title: x.title })" :aria-expanded="menuTarget===x.id" @click="showMenu($event,x.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg></button></div>
<p class="meta history-local-note">{{ tr("会话仅保存在此浏览器", "Conversations are stored only in this browser") }}</p>
</aside></aside></Transition>
<Teleport to="body"><div v-if="menuTarget" class="conversation-menu" :style="menuPosition" :aria-label="tr('会话操作', 'Conversation actions')"><button @click="rename(menuTarget)">{{ tr("重命名", "Rename") }}</button><button @click="exportActive(menuTarget)">{{ tr("导出会话", "Export conversation") }}</button><button class="danger" @click="remove(menuTarget)">{{ tr("删除会话", "Delete conversation") }}</button></div>
<dialog ref="renameDialog" class="conversation-rename" aria-labelledby="rename-title"><form @submit.prevent="saveName"><h2 id="rename-title">{{ tr("重命名会话", "Rename conversation") }}</h2><label>{{ tr("会话名称", "Conversation name") }}<input ref="renameInput" v-model="renameTitle" maxlength="60" required /></label><div class="row"><button type="button" class="quiet-button" @click="renameDialog?.close()">{{ tr("取消", "Cancel") }}</button><button class="primary" type="submit" :disabled="!renameTitle.trim()">{{ tr("保存", "Save") }}</button></div></form></dialog></Teleport>
</template>
